    const MAX_RESULTADOS = 35;

    function normalizar(txt) {
        return String(txt || '')
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase()
            .replace(/ç/g, 'c')
            .replace(/[^a-z0-9]+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function escapeHtml(txt) {
        return String(txt || '').replace(/[&<>"']/g, m => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
        }[m]));
    }

    function scoreItem(item, termoNorm) {
        if (!termoNorm) return 0;
        const codigo = normalizar(item.codigo);
        const nome = normalizar(item.nome);
        const grupo = normalizar(item.grupo);
        const uso = normalizar(item.uso);
        let score = 0;
        if (codigo === termoNorm) score += 300;
        if (codigo.startsWith(termoNorm)) score += 180;
        if (nome === termoNorm) score += 160;
        if (nome.startsWith(termoNorm)) score += 140;
        if (nome.includes(termoNorm)) score += 100;
        if (grupo.includes(termoNorm)) score += 55;
        if (uso.includes(termoNorm)) score += 45;
        (item.flags || []).forEach(x => { if (normalizar(x).includes(termoNorm)) score += 48; });
        (item.funcoes || []).forEach(x => { if (normalizar(x).includes(termoNorm)) score += 42; });
        (item.campos || []).forEach(x => { if (normalizar(x).includes(termoNorm)) score += 28; });
        (item.aliases || []).forEach(x => { if (normalizar(x).includes(termoNorm)) score += 38; });
        const partes = termoNorm.split(' ').filter(Boolean);
        if (partes.length > 1) {
            partes.forEach(p => {
                if (nome.includes(p)) score += 18;
                if (uso.includes(p)) score += 10;
                if (item.index.includes(p)) score += 8;
            });
        }
        return score;
    }

    function pesquisar(termo) {
        const termoNorm = normalizar(termo);
        if (!termoNorm) return [];
        return BASE
            .filter(item => item.index.includes(termoNorm) || normalizar(item.codigo).includes(termoNorm) || normalizar(item.nome).includes(termoNorm))
            .map(item => ({ ...item, _score: scoreItem(item, termoNorm) }))
            .sort((a, b) => b._score - a._score || String(a.codigo).localeCompare(String(b.codigo), 'pt-BR', { numeric: true }))
            .slice(0, MAX_RESULTADOS);
    }

